Q: Type-erased async operation initiation A: <p>First and foremost, <code>final</code> implies virtual, so cannot be a template.</p>
<p>Second, <code>wrap</code> moved <code>h</code>, but you don't use it. Why was it there?</p>
<p>Third:</p>
<blockquote>
<p>but this doc suggests that some completion tokens may choose to defer execution of the initiation function, which presumably would be a problem</p>
</blockquote>
<p>It's not a problem because you only take by value and even the semantics of <code>const_buffer</code> don't change: the referenced data needs to stay alive until completion regardless. I would absolutely consider making that part of <code>entry</code> (e.g. <code>pair&lt;std::string, handler_type&gt;</code>), which is in part why a <code>deque</code> was chosen (it has reference stability when pushed/popped from either end).</p>
<p>This sample compiles fine: <a href="https://coliru.stacked-crooked.com/a/40f4576cb0f3e91b" rel="nofollow noreferrer">Live On Coliru</a></p>
<pre class="lang-cpp prettyprint-override"><code>#include &lt;boost/asio.hpp&gt;
#include &lt;deque&gt;
using namespace std::literals;

namespace asio = boost::asio;
using tcp      = asio::ip::tcp;
using boost::system::error_code;

class sender {
  public:
    virtual ~sender() = default;

    template &lt;typename Token&gt; auto async_send_message(asio::const_buffer buf, Token&amp;&amp; token) {
        auto init = [this](auto handler, asio::const_buffer buf) {
            do_async_send_message(buf, std::move(handler));
        };

        return asio::async_initiate&lt;Token, void(std::error_code)&gt;(init, std::forward&lt;Token&gt;(token), buf);
    }

  private:
    virtual void do_async_send_message(asio::const_buffer                             buf,
                                       asio::any_completion_handler&lt;void(error_code)&gt; h) = 0;
};

class sender_impl
    : public sender
    , public std::enable_shared_from_this&lt;sender_impl&gt; {
  public:
    explicit sender_impl(tcp::socket sock) : _socket(std::move(sock)) {}

  private:
    void do_async_send_message(asio::const_buffer                             buf,
                               asio::any_completion_handler&lt;void(error_code)&gt; h) final {

        // Initiate the async operation on the socket's strand
        asio::dispatch(_socket.get_executor(), //
                       [this, me = shared_from_this(), buf, h = std::move(h)] mutable {
                           async_send_message_impl(buf, std::move(h));
                       });
    }

    template &lt;typename Handler&gt; void async_send_message_impl(asio::const_buffer buf, Handler h) {
        _send_queue.emplace_back(buf, std::move(h));

        // Queue was empty meaning there's no active send loop, so start one.
        if (_send_queue.size() == 1)
            send_loop();
    }

    void send_loop() {
        if (_send_queue.empty())
            return;

        asio::async_write( //
            _socket, _send_queue.front().first, [this, me = shared_from_this()](error_code ec, std::size_t) {
                auto&amp;       h  = _send_queue.front().second;
                auto const&amp; ex = asio::get_associated_executor(h, _socket.get_executor());
                asio::dispatch(ex, [h = std::move(h), ec]() mutable { h(ec); });

                if (!ec.failed()) {
                    // Keep sending until no messages left to send.
                    _send_queue.pop_front();
                    send_loop();
                }
            });
    }

    using handler_type = asio::any_completion_handler&lt;void(error_code const&amp;)&gt;;
    using entry        = std::pair&lt;asio::const_buffer, handler_type&gt;;
    tcp::socket       _socket;
    std::deque&lt;entry&gt; _send_queue;
};

int main() {
    asio::thread_pool ioc(1);
    tcp::socket       s(ioc);
    s.connect({{}, 8989});

    std::shared_ptr&lt;sender&gt; ps = std::make_shared&lt;sender_impl&gt;(std::move(s));

    ps-&gt;async_send_message(asio::buffer(&quot;hello world\n&quot;sv), asio::detached);

    ioc.join();
}
</code></pre>
